int nonReentrantRecursive(int n) {
    if(n == 0) {
        i = 1;
        return 1;
    } else {
        i = n * nonReentrantRecursive(n - 1);
        return i;
    }
}

int reentrantRecursive(int n, int i) {
    if(n == 0) {
        return i * 1;
    } else {
        return reentrantRecursive(n - 1, i * n);
    }
}

